// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address nonOwner, uint256 balance) public {
        vm.assume(nonOwner != address(this));
        vm.deal(address(c), balance);

        bool succeeded;
        vm.prank(nonOwner);
        try c.withdrawAll(nonOwner) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        assertTrue(!succeeded);
    }
}
